import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"比","description":"焦氏易林注 - 比","frontmatter":{"title":"比","description":"焦氏易林注 - 比"},"headers":[],"relativePath":"zh/classics/jiaoyilin/008.md","filePath":"zh/classics/jiaoyilin/008.md"}'),l={name:"zh/classics/jiaoyilin/008.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="比" tabindex="-1">比 <a class="header-anchor" href="#比" aria-label="Permalink to “比”">​</a></h1><h3 id="比-1" tabindex="-1">比 <a class="header-anchor" href="#比-1" aria-label="Permalink to “比”">​</a></h3><h3 id="比之乾" tabindex="-1">比之乾 <a class="header-anchor" href="#比之乾" aria-label="Permalink to “比之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>繼祖復宗，追明成康。光照萬國，享世久長。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>乾為祖宗、為大明、為光、為久長，伏坤為萬國。</p><h3 id="比之坤" tabindex="-1">比之坤 <a class="header-anchor" href="#比之坤" aria-label="Permalink to “比之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>麟子鳳雛，生長嘉國。和氣所居，康樂溫仁，邦多哲人。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>坤為文、為麟鳳、為國、為邦，《遇》卦比坎為和、為明哲。艮火，故曰溫仁。○溫仁，依元本，宋本、汲古作無憂。</p><h3 id="比之屯" tabindex="-1">比之屯 <a class="header-anchor" href="#比之屯" aria-label="Permalink to “比之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>灼火泉源，釣鯉山巔。魚不可得，火不肯燃。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坎為泉，坤亦為水，而坎在上故為泉源。艮為火，在坎下，故曰灼火泉源。艮為山，坤為魚，艮手為釣，故曰釣鯉山巔。坤虛，故二者皆不可得。○火，依宋元本，汲古作灼灼，非。鯉，宋本作鰟。○坤魚艮火確象。</p><h3 id="比之蒙" tabindex="-1">比之蒙 <a class="header-anchor" href="#比之蒙" aria-label="Permalink to “比之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>彭生為豕，白龍作災。盜堯衣裳，桀跖荷兵。青禽照夜，三日夷傷。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為壽，故曰彭。老彭壽八百。震為生，坎為豕，《左傳》：「豕人立而啼，從者曰公子彭生」也。震為白、為龍。坎為災、為盜。震為帝故曰堯。震衣坤裳，坤為惡，故曰桀跖。艮為兵、為荷。震為馬。青禽、照夜，皆馬名。震東方，色青，艮鳥，故曰青禽。艮火坤夜，故曰照夜。坤為夷傷，伏離為日，震數三，故曰三日。○彭生，元本作彭名，依宋本、汲古。龍，宋本、汲古作虎，依元本校。照夜，依汲古，宋元作照火，非。</p><h3 id="比之需" tabindex="-1">比之需 <a class="header-anchor" href="#比之需" aria-label="Permalink to “比之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>黍稷醇醲，敬奉山宗。神嗜飲食，甘雨嘉降。庶物蕃殖，獨蒙福祉，時災不至。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>坎為酒，故曰醇醲。乾為宗，伏艮，故曰山宗。坎為飲食、為雨，伏坤為庶物。乾為福祉。○醲，依觀之坎校，宋本、汲古皆作醴。庶物，從元本，宋本、汲古作黎庶。又宋本無末句，茲從汲古。</p><h3 id="比之訟" tabindex="-1">比之訟 <a class="header-anchor" href="#比之訟" aria-label="Permalink to “比之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>李華再實，鴻卵降集。仁哲權輿，蔭國受福。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。震為李、為花。乾為實。震為鴻、為卵。坤為降集。震為仁。坎為哲。巽為權。震為輿、為蔭。坤為國。○卵，依汲古，宋元本作飛。○巽為權、震為鴻證。</p><h3 id="比之師" tabindex="-1">比之師 <a class="header-anchor" href="#比之師" aria-label="Permalink to “比之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>千歲之墟，大國所屠。不見子都，城空無家。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤為千歲、為墟、為國、為殺，故曰屠。震為子，坤為都，故曰子都。坎伏，故不見。《鄭風》語也。坤為城、為虛，故曰城空。艮為家，艮覆，故無家。家，音姑。○國，依宋元本，汲古作兵。</p><h3 id="比之比" tabindex="-1">比之比 <a class="header-anchor" href="#比之比" aria-label="Permalink to “比之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>鹿得美草，鳴呼其友。九族和睦，不憂飢乏。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為鹿，反震為草、為鳴呼。陰陽相遇為友，艮為友，以陽遇陰也，此謂九五也。坤為族，《漢上易》謂坤數九以乙至癸也，故曰九族。坎為和睦、為憂。坤虛為飢乏，比樂故不憂。○宋元本多「長子入獄，霜降族哭」八字，與上文意不屬，斷為衍文，依汲古。</p><h3 id="比之小畜" tabindex="-1">比之小畜 <a class="header-anchor" href="#比之小畜" aria-label="Permalink to “比之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>王孫公子，把彈攝丸。發輒有得，家室饒足。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。震為公子、為王，艮為孫，故曰王孫。坎為彈丸。艮子為把、為攝。震為發，坎為得。艮為家，坎為室，坤為饒足。</p><h3 id="比之履" tabindex="-1">比之履 <a class="header-anchor" href="#比之履" aria-label="Permalink to “比之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>驪姬讒喜，與二嬖謀。譖殺恭子，賊害忠孝。申生以縊，重耳奔逃。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>乾馬兌姬，故曰驪姬。正反兌相對，故曰讒。讒喜，言喜讒也。伏坎為謀、為嬖。嬖，愛也。兌卦數二，故曰二嬖。《左傳莊二十八年》：「驪姬嬖，賂外嬖梁五與東關嬖五，使譖太子於公而殺之」，伏坤為殺，震為子，巽為賊，坤為害，坤順為忠孝，故曰賊殺忠孝。震為申、為生，巽繩為縊，故曰申生以縊。坎為耳，坤為重，故曰重耳。震為奔逃。○喜，從宋本，汲古等本訛嬉。逃，從宋本，汲古作走。</p><h3 id="比之泰" tabindex="-1">比之泰 <a class="header-anchor" href="#比之泰" aria-label="Permalink to “比之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>長生無極，子孫千億。柏柱載梁，堅固不傾。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為長生、為子，伏艮為孫，乾為千萬。又坤眾，故曰千億。伏艮為柏、為梁柱、為堅固，故曰不傾。○梁，依汲古，宋元本皆作青，豈知梁與傾為韻。</p><h3 id="比之否" tabindex="-1">比之否 <a class="header-anchor" href="#比之否" aria-label="Permalink to “比之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>失意懷憂，如幽狴牢。亡子喪夫，附托寄居。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>卦《否》而象全用遇卦。《比》坎為意、為憂懷、為牢狴，坎陷，故曰幽。艮為子、為夫，坤為喪亡，故曰亡子喪夫。附托寄居，言陰順陽也。艮為居。</p><h3 id="比之同人" tabindex="-1">比之同人 <a class="header-anchor" href="#比之同人" aria-label="Permalink to “比之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>仁智隱伏，麟不可得。龍蛇潛藏，虛居堂室。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為仁，坎為智、為隱伏。坤文為麟，坤亡，故不可得。震龍巽蛇，巽伏，故曰龍蛇潛藏。坤為虛，坎為室，故曰虛居堂室。</p><h3 id="比之大有" tabindex="-1">比之大有 <a class="header-anchor" href="#比之大有" aria-label="Permalink to “比之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>挒潔堁堁，締結難解。嫫母衒嫁，媒不得坐，自為身禍。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>挒，捩也。潔、挈同，度也。《莊子人間世》：「見櫟社樹潔之百圍」是也。堁，塵起貌。《淮南子主術訓》：「揚堁而弭塵」是也。卦通《比》。《比》互艮手，故曰挒潔，言捩轉潔度而堁堁塵起也。下重坤，坤土，故曰堁堁。坎陷，故締結難解。［原書作結，誤。］坤惡，故曰嫫母。反震為嫁，離明在上，故曰衒嫁。坎為和合、為媒。艮為坐，坎陷，故不得坐。坤為自、為身、為禍。○挒潔，從宋元本，汲古作列潔。堁堁，從汲古，宋元本作纍纍。挒潔纍纍，言以手提潔下纍纍不絕，與重坤象亦合。然不若堁堁義深，於坤象尤合，且韻尤協。堁，音顆，與解、坐、禍為韻。</p><h3 id="比之謙" tabindex="-1">比之謙 <a class="header-anchor" href="#比之謙" aria-label="Permalink to “比之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>蜩飛墜木，不毀頭足。保我羽翼，復歸其室。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>伏巽為蜩，震為飛、為木、飛足。艮為頭，艮堅，故不毀。震為羽翼、為歸，艮為室。○蜩，從宋元本，汲古作鳥。</p><h3 id="比之豫" tabindex="-1">比之豫 <a class="header-anchor" href="#比之豫" aria-label="Permalink to “比之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>陳媯敬仲，兆興齊薑。乃適營邱，八世大昌。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳屯之噬嗑，象多同，故辭同。</p><h3 id="比之隨" tabindex="-1">比之隨 <a class="header-anchor" href="#比之隨" aria-label="Permalink to “比之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>過時不歸，雌雄苦悲。徘徊外國，與母分離。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮時震歸，艮止，故不歸。兌巽雌、艮震雄，中互大坎，故曰苦悲。艮為國、為外，艮止，故徘徊外國。巽為母，震行為離。</p><h3 id="比之蠱" tabindex="-1">比之蠱 <a class="header-anchor" href="#比之蠱" aria-label="Permalink to “比之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>齊魯爭言，戰於龍門。構怨結禍，三世不安。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>解見坤之離。《蠱》初至四與離中爻正反兌同，故語同，皆《易》困「有言不信」的註。○結，汲古作連，非。安作寧，失韻，尤非，依宋本校。</p><h3 id="比之臨" tabindex="-1">比之臨 <a class="header-anchor" href="#比之臨" aria-label="Permalink to “比之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>府藏之富，王以賑貸。捕魚河海，笱網多得。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>坤為府藏、為富，震為王、為賑。賑，振也。坤為魚、為河海，伏艮為捕。震為笱，伏巽為繩、為網。○笱網，宋元本訛苟願。</p><h3 id="比之觀" tabindex="-1">比之觀 <a class="header-anchor" href="#比之觀" aria-label="Permalink to “比之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>鳴鶴北飛，下就稻池。鱔鮪鰋鯉，眾多饒有。一笱獲兩，利得過倍。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>通《大壯》。震為鶴、為鳴、為飛，坤北，故北飛。兌為池，震為稻，坤下，故曰下就稻池。巽坤皆魚，故曰眾饒。震為筐、為笱，乾卦數一，故曰一笱。兌卦數二，故曰獲兩。巽為利市三倍，故曰過倍。○笱，依王謨本，宋元本作狗，汲古訛苟。</p><h3 id="比之噬嗑" tabindex="-1">比之噬嗑 <a class="header-anchor" href="#比之噬嗑" aria-label="Permalink to “比之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>蒼梧鬱林，道易利通。元龜象齒，寶貝南金，為吾福功。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為叢木，故曰蒼梧鬱林，皆南方郡。艮為郡，震南，故象之尤切。震艮皆為道路，坎為平，故道易利通。易，平易也。離艮皆為龜，艮黔，故曰元龜。震為齒，艮為象，故曰象齒。震為寶，艮為見、為金，離南，故曰南金。《詩魯頌》：「元龜象齒，大賂南金」。○福，依宋本，汲古作歸，非。○艮金證。</p><h3 id="比之賁" tabindex="-1">比之賁 <a class="header-anchor" href="#比之賁" aria-label="Permalink to “比之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>兩火爭明，雖鬬不傷。分離且忍，全我弟兄。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮火離火，故曰兩。三至上正反艮，故曰爭明，曰鬬。坎和，故不傷。坎為分離、為忍，震為伯、為兄，艮坎皆弟，震福，故得全。○艮火證</p><h3 id="比之剝" tabindex="-1">比之剝 <a class="header-anchor" href="#比之剝" aria-label="Permalink to “比之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>伯夷叔齊，貞廉之師。以德防患，憂禍不存。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>震為伯，震覆，故伯夷。夷，傷也。艮為叔，卦為大艮，故曰叔齊。艮為貞、為廉。廉，側隅也。《前漢賈誼傳》：「廉遠則堂高」，艮陽在上，故曰廉。坤為師、為患，艮為防，故曰防患。坤為憂禍，艮安，故無禍。</p><h3 id="比之復" tabindex="-1">比之復 <a class="header-anchor" href="#比之復" aria-label="Permalink to “比之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>伯去我東，髪櫛如蓬。展轉空床，內懷憂傷。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為伯、為去、為東。坤為我，震為發、為蓬，《衛風》詩語也。伏巽為床，坤虛，故曰空床，震動，故曰展轉空床。展轉，動貌也。坤為內、為懷，坤喪，故憂傷。○伯，依元本，汲古、宋本皆作季，非。○震髪證。</p><h3 id="比之無妄" tabindex="-1">比之無妄 <a class="header-anchor" href="#比之無妄" aria-label="Permalink to “比之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>百足俱行，相轉為強。三聖翼事，王室寵光。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>乾為百，震足，故曰百足。震為行、為輔、為強，《淮南子》：「百足之蟲，雖死不僵」，以扶之者眾也。扶、輔義同。乾為聖，震數三，故曰三聖。震為翼，伏坤為事，艮為室，震王，故曰王室。乾為寵，艮為光。○艮光證。</p><h3 id="比之大畜" tabindex="-1">比之大畜 <a class="header-anchor" href="#比之大畜" aria-label="Permalink to “比之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>壅遏堤防，水不得行。火盛陽光，陰霓伏藏，退還其鄉。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為壅遏、為堤防，乾為江河，艮止，故水不得行。艮為火、為光，陽在上，故曰陽光。巽為蟲，故曰霓，巽伏，故藏。震為歸，艮為鄉，故曰退還其鄉。○艮火證。</p><h3 id="比之頤" tabindex="-1">比之頤 <a class="header-anchor" href="#比之頤" aria-label="Permalink to “比之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>螣蛇乘龍，年歲飢凶，民食草蓬。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤為年歲，坤虛，故飢凶。坤為民，震為食，為草蓬。○螣，依元本，宋本、汲古作騰。又汲古第二句多「歲飢蓬蓬」四字，此由下二句而衍，宋元本無，從之。</p><h3 id="比之大過" tabindex="-1">比之大過 <a class="header-anchor" href="#比之大過" aria-label="Permalink to “比之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>鉛刀攻玉，堅不可得。盡我筋力，胝繭為疾。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。上艮為刀，坤柔，故曰鉛刀。震為玉，艮為攻、為堅。胝繭，手足病。《荀子子道篇》：「手足胼胝」註：皮厚也。《戰國策》：「足重繭而不休息」註：皮皺似繭也。艮為膚、為堅，故曰胝繭。又上艮手、下震足尤切，凡易用一字含數象每如此。○胝，從宋本，汲古訛眠。疾，宋元本作候，依汲古。○艮刀證。</p><h3 id="比之坎" tabindex="-1">比之坎 <a class="header-anchor" href="#比之坎" aria-label="Permalink to “比之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>恆山浦壽，高邑具在。陰氣下淋，洪水不處，牢人開戶。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>翟雲升雲：「《地理志》常山郡有靈壽、浦吾，皆山邑，故曰高邑。」按：中爻艮山坎北，故曰恆山。恆山，北岳也。坎為浦，艮為壽、為高、為邑。坎水，故曰陰氣下淋，上下坎，故曰洪水，震行，故不處。坎為牢，震為人、為開，艮為戶。○壽，從宋元本，汲古作泛。不，依宋本，汲古作弗，非。《易林》諱弗字，劉毓崧曰「昭帝名弗」，故易林無弗字，只汲古此處一見，後校宋元本果作不。又浦壽如翟解當作蒲，《漢書》作蒲吾，蒲與卦象方合。又牢，元本作勞，依宋本、汲古。</p><h3 id="比之離" tabindex="-1">比之離 <a class="header-anchor" href="#比之離" aria-label="Permalink to “比之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>比目四翼，來安我國。福善上堂，與我同床。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>重離，故曰比目。伏震為翼，卦數四，故曰四翼。伏艮為國、為安、為堂、為床。</p><h3 id="比之咸" tabindex="-1">比之咸 <a class="header-anchor" href="#比之咸" aria-label="Permalink to “比之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>杜口結舌，心中怫鬱。去災生患，莫所告冤。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>兌為口舌，互大坎，故杜口結舌，或取艮止亦通。坎為心、為憂，故怫鬱。坎為災患、為冤，兌口為告，在外，故無可告。○生患，宋元作患生，非。以患與冤協。</p><h3 id="比之恒" tabindex="-1">比之恒 <a class="header-anchor" href="#比之恒" aria-label="Permalink to “比之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>牽尾不前，逆理失臣，衛朔以奔。通《益》。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>艮為尾、為牽，坤下，故不前。坤為理、為逆、為臣，坤失，故曰失臣。震為衛、為奔，坤北為朔，故曰衛朔以奔。《左傳桓十六年》：「衛朔奔齊，朔以讒構得國致急子、壽子皆死」，逆理失臣，謂朔不義，為二公子所逐也。○衛，從元本，宋、汲古作惠。惟宋元多「忠莫往來」四字，在第三句。</p><h3 id="比之遯" tabindex="-1">比之遯 <a class="header-anchor" href="#比之遯" aria-label="Permalink to “比之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>早霜晚雪，傷害禾麥。捐功棄力，飢無所食。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳解在需之咸、遯，初至五與咸同，彼以兌為傷害，此以巽落。</p><h3 id="比之大壯" tabindex="-1">比之大壯 <a class="header-anchor" href="#比之大壯" aria-label="Permalink to “比之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>適戍失期，患生無知。懼以懷憂，發藏閉塞，邦國騷愁。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。艮為守，故曰適戍。艮為時，坤失，故曰失期。坤迷，故曰無知。坤為患、為憂懼、為藏、為閉塞，震為發，坤為邦國。○知，元本作斯，音訛。《左傳莊八年》：「齊侯使連稱、管至父戍葵丘，瓜時而往，及瓜而代，期戍，公問不至，二人因公子無知作亂」，惟局本作無知，不惟韻協，事當並於象恰合，宋本、汲古作聊益，非。懷，依元本，宋本作發，非。發藏，依宋元，汲古作開藏。</p><h3 id="比之晉" tabindex="-1">比之晉 <a class="header-anchor" href="#比之晉" aria-label="Permalink to “比之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>昊天白日，照臨我國，萬民康樂，咸賴嘉福。離為夏，故曰昊天、曰白日、曰照臨。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坤為我、為國、為萬民，反震為樂、為嘉福。</p><h3 id="比之明夷" tabindex="-1">比之明夷 <a class="header-anchor" href="#比之明夷" aria-label="Permalink to “比之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>元吉無咎，安寧不殆。時行則行，無之有悔。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為元吉，坎為殆，震為行。之，往也，言勿往則悔也。○汲古無下二句，從宋元本。</p><h3 id="比之家人" tabindex="-1">比之家人 <a class="header-anchor" href="#比之家人" aria-label="Permalink to “比之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>懿公淺愚，不受深謀。無援失國，為狄所賊。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>通《解》。震為公、為懿。懿，善也。坎為謀，艮為手、為國，艮覆，故無援，故失國。坤為夷狄，坎為賊。丁晏雲：《列女傳》「許穆夫人初許求之，齊亦求之，公將與許，女曰：『許小而遠，齊大而近，倘有戎寇，赴告大國。』懿公不聽」，故曰不受深謀。○謀，依宋元本，與愚協，汲古作「不深受諫」，失韻。</p><h3 id="比之睽" tabindex="-1">比之睽 <a class="header-anchor" href="#比之睽" aria-label="Permalink to “比之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>城上有烏，自名破家。呼喚鳩毒，為國患災。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>通《蹇》，解詳坤之蒙。蹇、蒙象同，故辭同。惟此以互離為烏。○烏、名，從宋本，汲古作鳥、作號，非。</p><h3 id="比之蹇" tabindex="-1">比之蹇 <a class="header-anchor" href="#比之蹇" aria-label="Permalink to “比之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>長股善走，趨步千里。王良嘉喜，伯樂在道，申見王母。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>巽為股、為長，故曰長股。《竹書》：「黃帝五十九年長股氏來賓」，又《淮南墜形訓》：「海外三十六國，自西北至西南有修股氏。」高誘曰：「修，長也。」淮南以父諱長，故改為修。長故善走。半震為走、為步、為千里、為王、為良、為嘉喜、為伯樂、為道。離為見。○嘉喜，依汲古，宋元本作嘉言，非。申見王母，從宋元本，汲古作「申生見母」，非。伯樂，依汲古，宋元作伯來。汲古多「下有由子」四字，似衍文。又申疑西之訛，言王良御穆王西見王母也。</p><h3 id="比之解" tabindex="-1">比之解 <a class="header-anchor" href="#比之解" aria-label="Permalink to “比之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>耕石山顛，費種家貧。無聊虛作，苗髪不生。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為耕，半艮為石、為山、為家。震為種，離虛，故貧。震為苗、為髪，離燥，故不生。○虛，依汲古，宋本作處。</p><h3 id="比之損" tabindex="-1">比之損 <a class="header-anchor" href="#比之損" aria-label="Permalink to “比之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>二人共路，東趨西步。千里之外，不相知處。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為人，兌卦數二，故曰二人。震為路，震東兌西，震為趨、為步，坤為千里，迷故不知。</p><h3 id="比之益" tabindex="-1">比之益 <a class="header-anchor" href="#比之益" aria-label="Permalink to “比之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>純服素裳，載主以興。德義茂生，天下歸仁。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>坤為服，色黑，故曰純服。震為白，坤為裳，故曰素裳。震為主、為載、為興、為德，坤為義、為天下，震為茂生、為歸、為仁。《史記周本紀》：「武王載木主觀兵孟津，八百諸侯皆歸周」。○素裳及主，從汲古，宋元本作黃裳、作載土，皆非。此時文王木主在軍，故素服黃裳皆吉服也。</p><h3 id="比之夬" tabindex="-1">比之夬 <a class="header-anchor" href="#比之夬" aria-label="Permalink to “比之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>玉銑鐵頤，倉庫空虛。賈市無盈，與利為仇。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾為玉、為金，兌為銑、為頤。銑，鐘口兩旁也。伏艮為倉庫，坤虛故空。巽為賈市、為利，巽覆，故不利。○玉，從汲古，宋元本作五，非。銑、頤，依宋本，汲古利作「玉銳鐵頭」，非。無，從宋本，汲古訛為。</p><h3 id="比之姤" tabindex="-1">比之姤 <a class="header-anchor" href="#比之姤" aria-label="Permalink to “比之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>登昆侖，入天門。過糟邱，宿玉泉。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>同惠歡，見仁君。乾為山、為行，在西北，故曰登昆侖。乾為天、為門戶。《內經》：「以戌亥為天門」，巽入，故曰入天門。巽為糟，乾為山，故曰糟邱。乾為玉，伏坤為水、為夜，故曰宿玉泉。伏震為樂，乾為君、為仁，《六韜》：「殷君喜為糟邱，回船酒池」，又《南史陳暄傳》：「暄好飲，語兄子秀曰：速營糟邱，吾將老焉」。○乾為山證可解《同人》升其高陵。○同惠歡，依汲古，宋元本作「問惠觀」，非。</p><h3 id="比之萃" tabindex="-1">比之萃 <a class="header-anchor" href="#比之萃" aria-label="Permalink to “比之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>團團白日，為月所食。損上毀下，鄭昭出走。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>乾為日，兌為月，乾上缺，故曰為月所食。兌為毀折，在上，故曰損。上互巽，故曰毀，下坤為鄭，艮為光明、為昭，故曰鄭昭。伏震為出走。《左傳桓十一年》：「鄭昭公立，四月出奔衛」。</p><h3 id="比之升" tabindex="-1">比之升 <a class="header-anchor" href="#比之升" aria-label="Permalink to “比之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>倉盈庾億，宜稼黍稷。年歲有息，國家富有。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>伏艮為倉庾，為多，故曰盈億。震為稼、為黍稷、為年歲、為生，故曰息。坤為國、為富有。○年歲有息，依宋本，汲古作「年豐歲熟」。</p><h3 id="比之困" tabindex="-1">比之困 <a class="header-anchor" href="#比之困" aria-label="Permalink to “比之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>虎狼結謀，相聚為保。伺嚙牛羊，道絕不通，傷我商人。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。艮為虎狼，坎為謀、為聚，艮止為伺，兌為羊、為嚙，離為牛，故曰伺嚙牛羊。艮為道，坎陷，故不通。兌為傷，震為商人。○伺嚙，依宋元本，汲本訛思嚼，他本或訛同齒。</p><h3 id="比之井" tabindex="-1">比之井 <a class="header-anchor" href="#比之井" aria-label="Permalink to “比之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>中年摧折，常恐不活。老賴福慶，光榮相輔。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>坎為中，兌為摧折。伏震為年，初四大過死，故曰不活。坎為恐也。伏艮為壽、為老，震為福慶，艮為光榮。兌為輔，正伏象互用。○中，從汲古，宋本作木。相輔，元本作輔相，依宋本。</p><h3 id="比之革" tabindex="-1">比之革 <a class="header-anchor" href="#比之革" aria-label="Permalink to “比之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>同載共車，中道分去。喪我元夫，獨與孤居。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為車、為載。坤亦為車，故曰同載共車。艮為道，震為去，正反艮亦正反震，所向不同，故曰分去。坤為喪，震為夫、為長，故曰喪我元夫。艮為居、為獨，震為孤，艮震對，故獨與孤居。○與，從汲古，宋元作為。居，從元本，宋本、汲古作苦，失韻。</p><h3 id="比之鼎" tabindex="-1">比之鼎 <a class="header-anchor" href="#比之鼎" aria-label="Permalink to “比之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>飲酒醉酗，距跳爭訟。伯傷叔僵，東家治喪。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>兌為飲。通《屯》。坎為酒，坤迷。震為決躁，故曰醉酗、曰距跳。正反震，故爭訟。震為伯，艮為叔，坤死為僵、為傷，震為東，艮為家，坤喪，艮手為治，故曰東家治喪。○距跳，宋元作跳躍，依汲古。訟，宋元、汲古皆作鬬，依王謨本。</p><h3 id="比之震" tabindex="-1">比之震 <a class="header-anchor" href="#比之震" aria-label="Permalink to “比之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>出值凶災，逢五赤頭。跳言死格，扶伏聽命，不敢動搖。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為出，坎為災凶。坎數五，為頭、為赤，故曰逢五赤頭。震為言、為跳，艮手為格，初四伏大過死，故曰死格。扶伏，丁晏雲：與扶服同，即匍匐也，坎伏，故曰匍匐。坎為耳，故曰聽。伏巽為命。震為搖動，坎懼，故不敢。○跳，依宋與汲古，元本訛姚。死格，依宋元本，汲古作無佑，非。扶伏，依元本，宋本、汲古作扶杖，非。扶伏，即匍匐。聽命，依無妄之中孚校，元本作「扶伏伏聽」，非。</p><h3 id="比之艮" tabindex="-1">比之艮 <a class="header-anchor" href="#比之艮" aria-label="Permalink to “比之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>狼虎爭強，禮義不行。兼吞其國，齊魯無王。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為虎狼，三至上正反艮，故曰爭強。坤為禮義，艮止，故不行。言坤變艮也。震口為吞，艮為國，伏巽為齊，兌為魯，震為王，震覆，故無王。○齊魯，宋元本作齊晉，依汲古。王，宋元本作主，依汲古。</p><h3 id="比之漸" tabindex="-1">比之漸 <a class="header-anchor" href="#比之漸" aria-label="Permalink to “比之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>南國少子，才略美好。求我長女，賤薄不與。反得醜惡，後方大悔。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮國、艮少，離南，艮巽皆為材，伏兌為美好。艮為求，巽為長女。坎為薄，離為醜惡。伏震為後，坎為悔。此林屢見，殆有故實。陳樸園雲：觀明夷之噬嗑雲：仲氏爰歸，及此林乃知南國本求婚長女，而女家不與，但以仲女往媵，迨嫡不以媵備數，故明夷之噬嗑雲：不我肯顧，乃大悔恨，後其長女反得醜惡，故亦悔也。其它林詞類此者皆指此事。○才略，依元本，汲古宋作方，系形訛。賤薄，依汲古，宋元作薄賤。</p><h3 id="比之歸妹" tabindex="-1">比之歸妹 <a class="header-anchor" href="#比之歸妹" aria-label="Permalink to “比之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>一身兩頭，莫適其軀。無見我心，亂不可治。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>通《漸》。艮為身，坎數一，故曰一身。坎為頭，兌卦數二，故曰兩頭。坎為心、為隱，故不見。互離為亂。○無見我心，依汲古，宋本無此句。不可治下多「孰為湯漢」四字，費解，故不從。</p><h3 id="比之豐" tabindex="-1">比之豐 <a class="header-anchor" href="#比之豐" aria-label="Permalink to “比之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>李耳巢鵲，更相恐怯。偃爾以腹，不能距格。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>丁晏雲：《廣雅釋獸》：「於●，李耳，虎也」，《爾雅釋獸》：「匯，毛刺」，註雲：今蝟。《史記龜策傳》：「蝟能伏虎，見鵲仰腹」，虎畏蝟，蝟畏鵲，故雲更相恐怯。按：卦通《渙》，坎為耳，震為李，故曰李耳。坎為棘、為蝟，艮為鳥、為鵲，坎為恐怯，離為腹，在下，故曰偃。震為距格，巽順，故不能。○匯，汲古誤槖，相作逢，均非，均依宋元本。</p><h3 id="比之旅" tabindex="-1">比之旅 <a class="header-anchor" href="#比之旅" aria-label="Permalink to “比之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>柏桂棟梁，相輔為強。入敷五教，五室寧康。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>艮為木、為堅，故曰柏桂、曰棟梁。兌為輔、為強，巽卦數五，又為命令，為入，故曰入敷五教。艮為室，伏震為王、為樂，故曰寧康。○桂，依汲古，宋元本作松柏。入敷，從汲古，宋元作八哲。寧康，從元本，宋作康寧。</p><h3 id="比之巽" tabindex="-1">比之巽 <a class="header-anchor" href="#比之巽" aria-label="Permalink to “比之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>雀行求食，暮歸孚乳。反其室舍，安寧無故。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通《震》。艮為雀，震為行、為食，艮求。坎為暮、為孚，《說文》：「卵，孚也」，楊子《方言》：「雞伏卵而未孚」，艮為乳、為室舍，震為反，艮為安康。○孚，依宋元本，汲古作呼。無，依元本，宋、汲古作如。</p><h3 id="比之兌" tabindex="-1">比之兌 <a class="header-anchor" href="#比之兌" aria-label="Permalink to “比之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>四尾六頭，為凶作妖。陰不奉陽，上失其明。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。為尾，震卦數四，故曰四尾。坎為頭，卦數六，故曰六頭。坎為凶、為妖，兌上下卦陰在上，故曰陰不奉陽。兌昧，故上失其明。</p><h3 id="比之渙" tabindex="-1">比之渙 <a class="header-anchor" href="#比之渙" aria-label="Permalink to “比之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>一衣三關，結緝不便。歧道異路，日暮不到。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為衣，坎數一，故曰一衣。艮為關，數三，故曰三關。關，即結束，如今之紐扣。坎為合，故曰結緝，坎陷，故不便。艮震皆為道路，二五正反艮震，所向不同，故曰歧道異路。坎為暮，離為日，離伏，故曰日暮不到。○衣，從宋本，汲古作旅，非。翟雲升據李白詩謂結緝即與同行者相結合，豈知宋本旅作衣，結緝謂衣也。關，宋元本作闕，今依汲古。</p><h3 id="比之節" tabindex="-1">比之節 <a class="header-anchor" href="#比之節" aria-label="Permalink to “比之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>牙櫱生齒，室堂啟戶。幽人利貞，鼓翼起舞。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>牙、芽通。震為牙櫱，兌為齒，言齒初生若草木之芽櫱也。艮為堂戶，震為啟，艮為幽人。又坎為幽，震為人，亦合。震為鼓、為翼、為起舞。○櫱，依汲古，宋元本作孽。堂，宋元本作當，依汲古。</p><h3 id="比之中孚" tabindex="-1">比之中孚 <a class="header-anchor" href="#比之中孚" aria-label="Permalink to “比之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>春鴻飛東，以馬貨金。利得十倍，重載歸鄉。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為東、為春、為鴻、為飛、為馬。艮為金，震為商旅，與艮對，故曰以馬貨金。《玉篇》：「貨，賣也」。巽為利，兌數十，故曰十倍。震為載、為歸，艮為鄉。○貨，從汲古，宋元本作質。○艮為金證。</p><h3 id="比之小過" tabindex="-1">比之小過 <a class="header-anchor" href="#比之小過" aria-label="Permalink to “比之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>歡悅以喜，子孫具在。守發能忍，不見殃咎。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為樂、為子，艮為孫，故曰子孫具在。具者，備也。艮為守、為忍，震為發。○具，從宋元本，汲古作俱，非。發，依宋元本，守發者，言或止或作，艮震象也，汲古作守強，非。</p><h3 id="比之既濟" tabindex="-1">比之既濟 <a class="header-anchor" href="#比之既濟" aria-label="Permalink to “比之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>精神銷落，形骸醜惡。齟齬頓挫，枯槁腐蠹。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《比》象。坎為精，坤死，故銷落。坤為形、為醜惡，伏兌為齒牙，正反兌故曰齟齬。伏離為枯槁。○齟齬頓挫，從汲古，宋元本作「齬齷挫頓」。</p><h3 id="比之未濟" tabindex="-1">比之未濟 <a class="header-anchor" href="#比之未濟" aria-label="Permalink to “比之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>登高上山，見王自言。申理我冤，得職蒙恩。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>艮為山，震為登、為王、為申明。坎為冤，艮為官，坎為恩，故曰得職。多用半象。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
